import sys

def insertion_sort(words):
    for i in range(1, len(words)):
        key = words[i]
        j = i - 1
        while j >= 0 and words[j] > key:
            words[j + 1] = words[j]
            j -= 1
        words[j + 1] = key
    return words

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    words = data[1:n+1]
    insertion_sort(words)
    for word in words:
        print(word)

if __name__ == "__main__":
    main()
